{
  "name": "通用GPIO设备",
  "name_en": "Generic GPIO Device",
  "manufacturer": "",
  "description": "通过单个 GPIO 引脚连接到单板计算机或控制器的通用外设类别，可对应简单的数字输入/输出元件，如按钮、开关、指示灯或逻辑电平传感器。在实验室、教学和原型开发中常用于基础电子接口测试、状态检测与简单控制。",
  "description_en": "A generic class of peripherals connected through a single GPIO pin to a single-board computer or controller. It can represent simple digital input/output components such as buttons, switches, indicator LEDs, or logic-level sensors. In labs, teaching, and prototyping, it is commonly used for basic electronics interfacing, state sensing, and simple control.",
  "tag_hints": [
    "GPIO",
    "single-pin peripheral",
    "digital input/output",
    "embedded prototyping",
    "lab electronics",
    "sensor interfacing",
    "simple actuator control"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭设备并释放所占用的 GPIO 引脚。",
      "description_en": "Close the device and release the occupied GPIO pin."
    },
    {
      "action_name": "auto-closed",
      "description": "获取设备是否已关闭。",
      "description_en": "Get whether the device is closed."
    },
    {
      "action_name": "auto-pin",
      "description": "获取设备连接的 GPIO 引脚。",
      "description_en": "Get the GPIO pin connected to the device."
    },
    {
      "action_name": "auto-value",
      "description": "获取设备当前数值状态。",
      "description_en": "Get the current value/state of the device."
    },
    {
      "action_name": "auto-ensure_pin_factory",
      "description": "确保 GPIO 引脚控制工厂已就绪。",
      "description_en": "Ensure the GPIO pin factory is available."
    },
    {
      "action_name": "auto-is_active",
      "description": "获取设备是否处于活动状态。",
      "description_en": "Get whether the device is active."
    },
    {
      "action_name": "auto-all",
      "description": "获取该类设备的全部实例集合。",
      "description_en": "Get the collection of all instances of this device class."
    },
    {
      "action_name": "auto-namedtuple",
      "description": "定义用于组织设备值的命名元组结构。",
      "description_en": "Define the named tuple structure used to organize device values."
    }
  ]
}

